const $ = s => document.querySelector(s);
const state = {slides:[], devices:[], board:null, session:null, config:JSON.parse(localStorage.getItem('bacheca.cloud')||'null')||{url:'https://ycbptntmbolfxkpfzxbj.supabase.co',key:'sb_publishable_gNfIiDYSqo0jySpgJuD-FA_1iP8RABq'}, demo:true, preview:0, busy:false};
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6000);}
function modal(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modal').showModal();}
$('#closeModal').onclick=()=>$('#modal').close();
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
const db = await new Promise((resolve,reject)=>{const r=indexedDB.open('bacheca-demo',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
function localGet(){return new Promise((resolve,reject)=>{const r=db.transaction('data').objectStore('data').get('board');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function localSave(value){return new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(value,'board');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
function sample(title,subtitle,accent='#4b674d'){return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="800" viewBox="0 0 1280 800"><rect width="1280" height="800" fill="#f4f3e8"/><rect x="52" y="52" width="1176" height="696" fill="none" stroke="#d2d9c5" stroke-width="2"/><text x="640" y="160" text-anchor="middle" fill="${accent}" font-family="Arial" font-size="20" letter-spacing="6">LA BACHECA DEL CONDOMINIO</text><path d="M570 240h140m-70-30v60" stroke="${accent}" stroke-width="3"/><text x="640" y="380" text-anchor="middle" fill="${accent}" font-family="Georgia" font-size="66">${title}</text><text x="640" y="460" text-anchor="middle" fill="#88917b" font-family="Arial" font-size="26">${subtitle}</text><text x="640" y="665" text-anchor="middle" fill="#98a189" font-family="Arial" font-size="17">ESEMPIO · Sostituiscilo con i tuoi avvisi</text></svg>`);}
async function demo(){state.demo=true;state.devices=[];state.session=null;const saved=await localGet();state.board={name:saved?.name||'Il tuo condominio'};state.slides=saved?.slides||[{id:'sample1',title:'Assemblea condominiale',url:sample('Assemblea condominiale','Uno spazio per decidere insieme.'),active:true,position:0},{id:'sample2',title:'Cura degli spazi comuni',url:sample('Gli spazi di tutti','Piccole attenzioni, ogni giorno.','#5d7368'),active:true,position:1},{id:'sample3',title:'Comunicazioni e contatti',url:sample('Restiamo in contatto','Tutte le informazioni, in un solo posto.','#7d7158'),active:true,position:2}];render();}
async function persist(){if(state.demo)await localSave({name:state.board.name,slides:state.slides});}
async function api(path,options={}){
  if(state.session && state.session.expires_at < Date.now()+60000)await refresh();
  const headers={apikey:state.config.key,...options.headers};
  if(state.session)headers.Authorization='Bearer '+state.session.access_token;
  if(options.body && !(options.body instanceof Blob)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}
  const r=await fetch(state.config.url+path,{...options,headers});
  const text=await r.text();
  let data=null;
  if(text.trim()){
    try{data=JSON.parse(text);}catch{
      if(r.ok)throw new Error('Risposta del server non valida. Ricarica la bacheca per verificare il salvataggio.');
    }
  }
  if(!r.ok){const error=new Error(data?.msg||data?.message||data?.error_description||data?.error||'Richiesta non riuscita ('+r.status+')');error.status=r.status;throw error;}
  return data;
}
function setSession(s){state.session={...s,expires_at:Date.now()+s.expires_in*1000};sessionStorage.setItem('bacheca.session',JSON.stringify(state.session));}
async function refresh(){const r=await fetch(state.config.url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:state.config.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:state.session.refresh_token})});if(!r.ok){state.session=null;sessionStorage.removeItem('bacheca.session');throw new Error('Sessione scaduta. Accedi di nuovo.');}setSession(await r.json());}
async function loadCloud(){state.board=await api('/rest/v1/rpc/ensure_board',{method:'POST',body:{}});await reloadCloud();state.demo=false;render();}
async function reloadCloud(){const rows=await api('/rest/v1/slides?board_id=eq.'+state.board.id+'&order=position.asc,created_at.asc');const slides=await Promise.all(rows.map(async s=>{const v=await api('/storage/v1/object/sign/notices/'+s.path,{method:'POST',body:{expiresIn:3600}});return {...s,url:state.config.url+'/storage/v1'+v.signedURL};}));state.slides=slides;state.devices=await api('/rest/v1/devices?board_id=eq.'+state.board.id+'&select=id,name,last_seen,revoked&order=created_at.desc');}
function render(){const active=state.slides.filter(s=>s.active);$('#totalStat').textContent=active.length;$('#navCount').textContent=state.slides.length;$('#listCount').textContent=state.slides.length;$('#screensStat').textContent=state.demo?'—':state.devices.filter(d=>!d.revoked).length;$('#modeLabel').textContent=state.demo?'Modalità demo':'Account collegato';$('#demoBanner').hidden=!state.demo;$('#buildingName').textContent=state.board?.name||'Il tuo condominio';$('#boardName').value=state.board?.name||'';$('#logout').hidden=state.demo;$('#cloudSummary').textContent=state.demo?'Stai usando la demo locale. Nessun avviso viene inviato al PC.':'Collegato a '+state.config.url+'. Gli avvisi attivi sono disponibili ai PC abbinati.';$('#noticeList').innerHTML=state.slides.length?state.slides.map((s,i)=>`<article class="notice-row ${s.active?'':'inactive'}"><span class="row-number">${String(i+1).padStart(2,'0')}</span><img class="thumbnail" src="${esc(s.url)}" alt=""><div class="notice-info"><strong>${esc(s.title)}</strong><small>${state.demo&&s.id.startsWith('sample')?'Avviso di esempio':s.width?s.width+' × '+s.height+' px':'Immagine'} · 30 secondi</small></div><div class="row-actions"><div class="reorder"><button class="icon-button" data-action="up" data-id="${s.id}" aria-label="Sposta su" ${i===0?'disabled':''}>▲</button><button class="icon-button" data-action="down" data-id="${s.id}" aria-label="Sposta giù" ${i===state.slides.length-1?'disabled':''}>▼</button></div><button class="toggle ${s.active?'':'off'}" data-action="toggle" data-id="${s.id}">${s.active?'Attivo':'In pausa'}</button><button class="icon-button" data-action="rename" data-id="${s.id}" aria-label="Rinomina">✎</button><button class="icon-button" data-action="delete" data-id="${s.id}" aria-label="Elimina">×</button></div></article>`).join(''):'<div class="empty">La bacheca è pronta per il tuo primo avviso.</div>';$('#devicesList').innerHTML=state.demo?'<p class="muted">Collega Supabase per gestire i dispositivi reali.</p>':state.devices.length?state.devices.map(d=>`<div class="device-row"><div><strong>${esc(d.name)}</strong><small>${d.revoked?'Accesso revocato':d.last_seen?'Ultimo contatto: '+new Date(d.last_seen).toLocaleString('it-IT'):'In attesa del primo collegamento'}</small></div>${d.revoked?'':`<button class="text-button revoke" data-id="${d.id}">Revoca accesso</button>`}</div>`).join(''):'<p class="muted">Nessun PC abbinato. Collega il tuo primo schermo.</p>';state.preview=0;renderPreview();}
function renderPreview(){const slides=state.slides.filter(s=>s.active);const s=slides[state.preview%Math.max(1,slides.length)];$('#monitorDisplay').innerHTML=s?`<img src="${esc(s.url)}" alt="${esc(s.title)}">`:'<span class="muted">La tua prossima comunicazione.</span>';$('#previewTitle').textContent=s?.title||'Nessun avviso attivo';$('#previewCounter').textContent=s?(state.preview%slides.length+1)+' / '+slides.length:'0 / 0';}
setInterval(()=>{state.preview++;renderPreview();},30000);
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===b));['avvisi','schermi','impostazioni'].forEach(v=>$('#'+v+'View').hidden=v!==b.dataset.view);$('#pageLabel').textContent=b.dataset.view[0].toUpperCase()+b.dataset.view.slice(1);});
function connect(){modal('Collega la tua bacheca',`<p>Inserisci URL e chiave pubblica del progetto Supabase già configurato con i file inclusi nel progetto. Non inserire mai una chiave service_role o secret.</p><form id="loginForm"><label>URL progetto Supabase<input id="supabaseUrl" type="url" placeholder="https://progetto.supabase.co" value="${esc(state.config?.url||'')}" required></label><label>Chiave pubblica / anon<input id="supabaseKey" autocomplete="off" value="${esc(state.config?.key||'')}" required></label><label>Email amministratore<input id="email" type="email" autocomplete="username" required></label><label>Password<input id="password" type="password" autocomplete="current-password" required></label><p>Crea prima l’utente amministratore nel pannello Supabase. Non è prevista registrazione pubblica.</p><button class="primary" type="submit">Accedi e collega</button></form>`);$('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const url=new URL($('#supabaseUrl').value.trim());if(url.protocol!=='https:'||!url.hostname.endsWith('.supabase.co'))throw new Error('Usa l’URL HTTPS del tuo progetto supabase.co.');const key=$('#supabaseKey').value.trim();if(key.startsWith('sb_secret_'))throw new Error('Serve la chiave pubblica, non una chiave segreta.');if(key.startsWith('eyJ')){try{const p=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));if(p.role==='service_role')throw new Error('SECRET');}catch(err){if(err.message==='SECRET')throw new Error('Non usare service_role nel sito.');}}state.config={url:url.origin,key};const s=await api('/auth/v1/token?grant_type=password',{method:'POST',body:{email:$('#email').value.trim(),password:$('#password').value}});setSession(s);localStorage.setItem('bacheca.cloud',JSON.stringify(state.config));await loadCloud();$('#modal').close();toast('Bacheca collegata. Ora puoi pubblicare i tuoi avvisi.');}catch(err){toast(err.message);}finally{b.disabled=false;}};}
['#connection','#connectBanner','#settingsConnect'].forEach(s=>$(s).onclick=connect);
$('#logout').onclick=async()=>{try{await api('/auth/v1/logout',{method:'POST'});}catch{}sessionStorage.removeItem('bacheca.session');await demo();toast('Sei tornato alla demo locale.');};
$('#saveBoard').onclick=async()=>{try{const name=$('#boardName').value.trim();if(!name)throw new Error('Inserisci un nome.');if(!state.demo)await api('/rest/v1/boards?id=eq.'+state.board.id,{method:'PATCH',body:{name}});state.board.name=name;await persist();render();toast('Nome salvato.');}catch(e){toast(e.message);}};
async function optimize(file){if(file.size>15*1024*1024)throw new Error(file.name+': supera 15 MB.');if(!['image/jpeg','image/png'].includes(file.type))throw new Error('Sono ammessi soltanto JPG e PNG.');const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>50000000)throw new Error('Immagine troppo grande.');const scale=Math.min(1,1600/bitmap.width,1200/bitmap.height);const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.87));if(!blob)throw new Error('Conversione immagine non riuscita.');return {blob,width:canvas.width,height:canvas.height};}finally{bitmap.close();}}
async function upload(files){if(state.busy)return;state.busy=true;$('#uploadButton').disabled=true;let added=0;try{for(const file of files){toast('Preparo '+file.name+'…');const {blob,width,height}=await optimize(file);const id=crypto.randomUUID();const sha256=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join('');const slide={id,title:file.name.replace(/\.[^.]+$/,''),position:state.slides.length,active:true,width,height,sha256};if(state.demo){slide.url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});state.slides.push(slide);await persist();}else{slide.board_id=state.board.id;slide.path=state.board.id+'/'+id+'.jpg';await api('/storage/v1/object/notices/'+slide.path,{method:'POST',headers:{'Content-Type':'image/jpeg','x-upsert':'false'},body:blob});try{await api('/rest/v1/slides',{method:'POST',body:slide});}catch(e){if(e.status>=400&&e.status<500&&e.status!==408)await api('/storage/v1/object/notices',{method:'DELETE',body:{prefixes:[slide.path]}}).catch(()=>{});throw e;}state.slides.push(slide);}added++;}if(!state.demo)await reloadCloud();render();toast(added+' immagini aggiunte'+(state.demo?' alla demo locale.':'. Il PC le riceverà al prossimo aggiornamento.'));}catch(e){if(!state.demo)await reloadCloud().catch(()=>{});render();toast(e.message);}finally{state.busy=false;$('#uploadButton').disabled=false;$('#files').value='';}}
$('#files').onchange=e=>upload([...e.target.files]);$('#uploadButton').onclick=()=>$('#files').click();$('#dropzone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#files').click();}};['dragenter','dragover'].forEach(n=>$('#dropzone').addEventListener(n,e=>{e.preventDefault();$('#dropzone').classList.add('dragover');}));$('#dropzone').ondragleave=()=>$('#dropzone').classList.remove('dragover');$('#dropzone').ondrop=e=>{e.preventDefault();$('#dropzone').classList.remove('dragover');upload([...e.dataTransfer.files]);};
$('#noticeList').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b||state.busy)return;const id=b.dataset.id;const i=state.slides.findIndex(s=>s.id===id);const s=state.slides[i];try{if(b.dataset.action==='delete'){modal('Eliminare questo avviso?',`<p>“${esc(s.title)}” verrà rimosso dalla sequenza. Il PC recepirà la modifica al prossimo collegamento.</p><button class="primary" id="confirmDelete">Elimina avviso</button>`);$('#confirmDelete').onclick=async()=>{try{if(!state.demo){await api('/rest/v1/slides?id=eq.'+id,{method:'DELETE'});await api('/storage/v1/object/notices',{method:'DELETE',body:{prefixes:[s.path]}}).catch(()=>toast('Avviso rimosso. Il file residuo può essere eliminato da Storage.'));}state.slides.splice(i,1);await persist();render();$('#modal').close();}catch(err){toast(err.message);}};return;}if(b.dataset.action==='rename'){modal('Rinomina avviso',`<form id="renameForm"><label>Titolo<input id="renameTitle" maxlength="120" value="${esc(s.title)}" required></label><button class="primary">Salva titolo</button></form>`);$('#renameForm').onsubmit=async ev=>{ev.preventDefault();try{const title=$('#renameTitle').value.trim();if(!title)return;if(!state.demo)await api('/rest/v1/slides?id=eq.'+id,{method:'PATCH',body:{title}});s.title=title;await persist();render();$('#modal').close();}catch(err){toast(err.message);}};return;}if(b.dataset.action==='toggle'){if(!state.demo)await api('/rest/v1/slides?id=eq.'+id,{method:'PATCH',body:{active:!s.active}});s.active=!s.active;}else{const j=i+(b.dataset.action==='up'?-1:1);if(j<0||j>=state.slides.length)return;const ids=state.slides.map(s=>s.id);[ids[i],ids[j]]=[ids[j],ids[i]];if(!state.demo)await api('/rest/v1/rpc/reorder_slides',{method:'POST',body:{p_board:state.board.id,p_ids:ids}});[state.slides[i],state.slides[j]]=[state.slides[j],state.slides[i]];}await persist();render();}catch(err){toast(err.message);}};
$('#previewButton').onclick=()=>{const slides=state.slides.filter(s=>s.active);if(!slides.length)return toast('Aggiungi o attiva almeno un avviso.');let i=0;modal('Anteprima della sequenza',`<img class="preview-large" id="largePreview" alt=""><div class="modal-buttons"><button class="secondary" id="previousPreview">← Precedente</button><button class="secondary" id="nextPreview">Successivo →</button><span id="largeCounter"></span></div><p>Questa anteprima è manuale. Sul PC ogni immagine dura 30 secondi.</p>`);const show=()=>{$('#largePreview').src=slides[i].url;$('#largePreview').alt=slides[i].title;$('#largeCounter').textContent=(i+1)+' / '+slides.length;};$('#previousPreview').onclick=()=>{i=(i+slides.length-1)%slides.length;show();};$('#nextPreview').onclick=()=>{i=(i+1)%slides.length;show();};show();};
function pair(){if(state.demo){connect();return;}modal('Collega un PC',`<p>Crea una configurazione riservata per il tuo schermo. Potrai revocarla in qualsiasi momento.</p><form id="pairForm"><label>Nome dello schermo<input id="deviceName" value="Schermo ingresso" maxlength="80" required></label><button class="primary">Genera configurazione</button></form>`);$('#pairForm').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const result=await api('/rest/v1/rpc/create_device',{method:'POST',body:{p_board:state.board.id,p_name:$('#deviceName').value.trim()}});const config=JSON.stringify({endpoint:state.config.url+'/functions/v1/screen',token:result.token},null,2);modal('Configurazione pronta',`<p>Nel player Windows premi <strong>F2</strong> e incolla questa configurazione. È una credenziale di sola lettura: conservala con cura. Il sito non potrà mostrarla di nuovo.</p><textarea id="pairConfig" readonly></textarea><button class="primary" id="copyPair">Copia configurazione</button>`);$('#pairConfig').value=config;$('#copyPair').onclick=async()=>{try{await navigator.clipboard.writeText(config);toast('Configurazione copiata.');}catch{$('#pairConfig').select();toast('Premi Ctrl+C per copiare.');}};await reloadCloud();render();}catch(err){toast(err.message);if($('#pairForm button'))$('#pairForm button').disabled=false;}};}
$('#pairButton').onclick=pair;$('#pairButton2').onclick=pair;$('#devicesList').onclick=async e=>{const b=e.target.closest('.revoke');if(!b)return;modal('Revocare questo dispositivo?',`<p>Non potrà più scaricare aggiornamenti. Le immagini già presenti sul disco del PC rimarranno disponibili offline.</p><button class="primary" id="confirmRevoke">Revoca accesso</button>`);$('#confirmRevoke').onclick=async()=>{try{await api('/rest/v1/devices?id=eq.'+b.dataset.id,{method:'PATCH',body:{revoked:true}});await reloadCloud();render();$('#modal').close();}catch(err){toast(err.message);}};};
try{const session=JSON.parse(sessionStorage.getItem('bacheca.session')||'null');if(state.config&&session){state.session=session;await loadCloud();}else await demo();}catch(err){await demo();toast('Cloud non disponibile: '+err.message);}
setInterval(async()=>{if(!state.demo&&!state.busy){try{await reloadCloud();render();}catch(e){toast('Aggiornamento non riuscito: '+e.message);}}},1800000);
